{
  "name": "anthropic-sdk-mocked-tool-use",
  "private": true,
  "type": "module",
  "scripts": {
    "test": "node --import tsx --test test/*.test.ts"
  },
  "dependencies": {
    "@anthropic-ai/sdk": "0.134.0",
    "zod": "4.6.7"
  },
  "devDependencies": {
    "tsx": "4.23.15",
    "@types/node": "24.19.2"
  }
}

import Anthropic from "@anthropic-ai/sdk";
import { z } from "zod";

const LookupInput = z.object({ sku: z.string().regex(/^[A-Z]+-\d+$/) });
export const tools: Anthropic.Tool[] = [{
  name: "lookup_stock",
  description: "Units in stock for a SKU",
  input_schema: { type: "object", properties: { sku: { type: "string" } }, required: ["sku"] },
}];

export async function ask(client: Anthropic, question: string, stock: (sku: string) => number) {
  const messages: Anthropic.MessageParam[] = [{ role: "user", content: question }];
  for (let i = 0; i < 5; i++) {
    const res = await client.messages.create({ model: "claude-sonnet-4-5", max_tokens: 512, messages, tools });
    messages.push({ role: "assistant", content: res.content });
    if (res.stop_reason !== "tool_use") return res.content.filter((b) => b.type === "text").map((b) => b.text).join("");
    const results: Anthropic.ToolResultBlockParam[] = [];
    for (const block of res.content) {
      if (block.type !== "tool_use") continue;
      const p = LookupInput.safeParse(block.input);
      results.push(p.success
        ? { type: "tool_result", tool_use_id: block.id, content: String(stock(p.data.sku)) }
        : { type: "tool_result", tool_use_id: block.id, content: "invalid sku", is_error: true });
    }
    messages.push({ role: "user", content: results });
  }
  throw new Error("too many turns");
}

import { test } from "node:test";
import assert from "node:assert/strict";
import Anthropic from "@anthropic-ai/sdk";
import { ask } from "../src/agent.ts";

const msg = (content: object[], stop_reason: string) => ({ id: "m", type: "message", role: "assistant", model: "claude-sonnet-4-5", content, stop_reason, stop_sequence: null, usage: { input_tokens: 1, output_tokens: 1 } });

function fake(replies: object[], seen: any[]) {
  const fetch = async (_u: any, init: any) => {
    seen.push(JSON.parse(init.body));
    return new Response(JSON.stringify(replies.shift()), { status: 200, headers: { "content-type": "application/json" } });
  };
  return new Anthropic({ apiKey: "test", baseURL: "http://mock.local", fetch: fetch as any, maxRetries: 0 });
}

test("runs the tool and returns the final text", async () => {
  const seen: any[] = [];
  const c = fake([
    msg([{ type: "tool_use", id: "tu1", name: "lookup_stock", input: { sku: "MUG-1" } }], "tool_use"),
    msg([{ type: "text", text: "There are 7 mugs." }], "end_turn"),
  ], seen);
  assert.equal(await ask(c, "How many mugs?", () => 7), "There are 7 mugs.");
  assert.deepEqual(seen[1].messages[2].content[0], { type: "tool_result", tool_use_id: "tu1", content: "7" });
});

test("invalid tool input is returned as is_error", async () => {
  const seen: any[] = [];
  const c = fake([
    msg([{ type: "tool_use", id: "tu1", name: "lookup_stock", input: { sku: "bad" } }], "tool_use"),
    msg([{ type: "text", text: "Need a valid SKU." }], "end_turn"),
  ], seen);
  await ask(c, "?", () => 0);
  assert.equal(seen[1].messages[2].content[0].is_error, true);
});

{
  "name": "anthropic-streaming-mock",
  "private": true,
  "type": "module",
  "scripts": {
    "test": "node --import tsx --test test/*.test.ts"
  },
  "dependencies": {
    "@anthropic-ai/sdk": "0.134.0"
  },
  "devDependencies": {
    "tsx": "4.23.15",
    "@types/node": "24.19.2"
  }
}

import Anthropic from "@anthropic-ai/sdk";

export async function streamReply(client: Anthropic, prompt: string, onText: (t: string) => void) {
  const stream = client.messages.stream({ model: "claude-sonnet-4-5", max_tokens: 256, messages: [{ role: "user", content: prompt }] });
  stream.on("text", onText);
  const final = await stream.finalMessage(); // resolves once message_stop arrives
  return { text: final.content.filter((b) => b.type === "text").map((b) => b.text).join(""), stop: final.stop_reason, outputTokens: final.usage.output_tokens };
}

import { test } from "node:test";
import assert from "node:assert/strict";
import Anthropic from "@anthropic-ai/sdk";
import { streamReply } from "../src/stream.ts";

const ev = (type: string, data: object) => `event: ${type}\ndata: ${JSON.stringify({ type, ...data })}\n\n`;
function client(events: string[]) {
  const fetch = async () => new Response(new ReadableStream({ start(c) { for (const e of events) c.enqueue(new TextEncoder().encode(e)); c.close(); } }), { status: 200, headers: { "content-type": "text/event-stream" } });
  return new Anthropic({ apiKey: "test", baseURL: "http://mock.local", fetch: fetch as any, maxRetries: 0 });
}

test("streams text deltas and builds the final message", async () => {
  const parts: string[] = [];
  const r = await streamReply(client([
    ev("message_start", { message: { id: "m1", type: "message", role: "assistant", model: "claude-sonnet-4-5", content: [], stop_reason: null, stop_sequence: null, usage: { input_tokens: 5, output_tokens: 1 } } }),
    ev("content_block_start", { index: 0, content_block: { type: "text", text: "" } }),
    ev("content_block_delta", { index: 0, delta: { type: "text_delta", text: "Hi " } }),
    ev("content_block_delta", { index: 0, delta: { type: "text_delta", text: "there" } }),
    ev("content_block_stop", { index: 0 }),
    ev("message_delta", { delta: { stop_reason: "end_turn", stop_sequence: null }, usage: { output_tokens: 3 } }),
    ev("message_stop", {}),
  ]), "hello", (t) => parts.push(t));
  assert.deepEqual(parts, ["Hi ", "there"]);
  assert.deepEqual(r, { text: "Hi there", stop: "end_turn", outputTokens: 3 });
});

test("stream error events reject", async () => {
  await assert.rejects(streamReply(client([ev("error", { error: { type: "overloaded_error", message: "Overloaded" } })]), "x", () => {}));
});

{
  "name": "apollo-server-dataloader-batching",
  "private": true,
  "type": "module",
  "scripts": {
    "test": "node --import tsx --test test/*.test.ts"
  },
  "dependencies": {
    "@apollo/server": "5.5.1",
    "graphql": "16.14.2",
    "dataloader": "2.2.3"
  },
  "devDependencies": {
    "tsx": "4.23.15",
    "@types/node": "26.6.5"
  }
}

import { ApolloServer } from "@apollo/server";
import { GraphQLError } from "graphql";
import DataLoader from "dataloader";

type Author = { id: string; name: string };
type Book = { id: string; title: string; authorId: string };

export const typeDefs = `#graphql
  type Author { id: ID!, name: String!, books: [Book!]! }
  type Book { id: ID!, title: String!, author: Author! }
  type Query { books: [Book!]!, author(id: ID!): Author }
  type Mutation { addBook(title: String!, authorId: ID!): Book! }
`;

/** Fake data source that records every batch call so tests can prove N+1 is gone. */
export function createDb() {
  const authors: Author[] = [{ id: "a1", name: "Ursula" }, { id: "a2", name: "Octavia" }, { id: "a3", name: "Iain" }];
  const books: Book[] = [
    { id: "b1", title: "The Dispossessed", authorId: "a1" },
    { id: "b2", title: "Kindred", authorId: "a2" },
    { id: "b3", title: "The Left Hand of Darkness", authorId: "a1" },
    { id: "b4", title: "Consider Phlebas", authorId: "a3" },
  ];
  const calls: string[][] = [];
  return {
    books, calls,
    authorsByIds: async (ids: readonly string[]) => { calls.push([...ids]); return ids.map((id) => authors.find((a) => a.id === id) ?? new Error(`author ${id} not found`)); },
    booksByAuthorIds: async (ids: readonly string[]) => ids.map((id) => books.filter((b) => b.authorId === id)),
  };
}
export type Db = ReturnType<typeof createDb>;

/** Loaders are created per request, so the cache never leaks between users. */
export function createContext(db: Db, user?: string) {
  return {
    db, user,
    loaders: {
      author: new DataLoader<string, Author>((ids) => db.authorsByIds(ids)),
      booksByAuthor: new DataLoader<string, Book[]>((ids) => db.booksByAuthorIds(ids)),
    },
  };
}
export type Ctx = ReturnType<typeof createContext>;

export const resolvers = {
  Query: {
    books: (_: unknown, __: unknown, ctx: Ctx) => ctx.db.books,
    author: (_: unknown, { id }: { id: string }, ctx: Ctx) => ctx.loaders.author.load(id).catch(() => null),
  },
  Book: { author: (b: Book, _: unknown, ctx: Ctx) => ctx.loaders.author.load(b.authorId) },
  Author: { books: (a: Author, _: unknown, ctx: Ctx) => ctx.loaders.booksByAuthor.load(a.id) },
  Mutation: {
    addBook: async (_: unknown, args: { title: string; authorId: string }, ctx: Ctx) => {
      if (!ctx.user) throw new GraphQLError("sign in first", { extensions: { code: "UNAUTHENTICATED" } });
      await ctx.loaders.author.load(args.authorId).catch(() => {
        throw new GraphQLError("unknown author", { extensions: { code: "BAD_USER_INPUT", field: "authorId" } });
      });
      const book = { id: `b${ctx.db.books.length + 1}`, ...args };
      ctx.db.books.push(book);
      ctx.loaders.booksByAuthor.clear(args.authorId); // invalidate the per-request cache after a write
      return book;
    },
  },
};

export const createServer = () => new ApolloServer<Ctx>({ typeDefs, resolvers });

import { test } from "node:test";
import assert from "node:assert/strict";
import { createServer, createDb, createContext } from "../src/server.ts";

/** executeOperation runs the full request pipeline in-process, no HTTP server needed. */
async function exec(query: string, variables?: Record<string, unknown>, user?: string, db = createDb()) {
  const server = createServer();
  const res = await server.executeOperation({ query, variables }, { contextValue: createContext(db, user) });
  await server.stop();
  assert.equal(res.body.kind, "single");
  return { result: JSON.parse(JSON.stringify((res.body as { singleResult: unknown }).singleResult)) as { data?: any; errors?: any[] }, db };
}

test("resolves nested authors with one batched lookup instead of N+1", async () => {
  const { result, db } = await exec("{ books { title author { name } } }");
  assert.equal(result.errors, undefined);
  assert.equal(result.data.books.length, 4);
  assert.equal(result.data.books[1].author.name, "Octavia");
  assert.deepEqual(db.calls, [["a1", "a2", "a3"]]); // deduped and batched in one tick
});

test("author with books, and null for an unknown id", async () => {
  const { result } = await exec(`query($id: ID!) { a: author(id: $id) { name books { title } } b: author(id: "zz") { name } }`, { id: "a1" });
  assert.deepEqual(result.data.a.books.map((b: { title: string }) => b.title), ["The Dispossessed", "The Left Hand of Darkness"]);
  assert.equal(result.data.b, null);
});

test("mutation requires a user and reports error codes in extensions", async () => {
  const anon = await exec(`mutation { addBook(title: "X", authorId: "a1") { id } }`);
  assert.equal(anon.result.errors?.[0].extensions.code, "UNAUTHENTICATED");
  const bad = await exec(`mutation { addBook(title: "X", authorId: "nope") { id } }`, undefined, "ada");
  assert.equal(bad.result.errors?.[0].extensions.code, "BAD_USER_INPUT");
  assert.equal(bad.result.errors?.[0].extensions.field, "authorId");
});

test("mutation writes and clears the loader cache so reads see the new book", async () => {
  const db = createDb();
  const server = createServer();
  const contextValue = createContext(db, "ada");
  const read = `{ author(id: "a3") { books { title } } }`;
  const before = await server.executeOperation({ query: read }, { contextValue });
  const added = await server.executeOperation({ query: `mutation { addBook(title: "Excession", authorId: "a3") { id author { name } } }` }, { contextValue });
  const after = await server.executeOperation({ query: read }, { contextValue });
  await server.stop();
  // graphql-js builds results with null prototypes; a JSON round trip makes them plain objects
  const data = (r: typeof before) => JSON.parse(JSON.stringify((r.body as any).singleResult.data));
  assert.equal(data(before).author.books.length, 1);
  assert.deepEqual(data(added).addBook, { id: "b5", author: { name: "Iain" } });
  assert.deepEqual(data(after).author.books.map((b: { title: string }) => b.title), ["Consider Phlebas", "Excession"]);
});

test("validation errors come back as GRAPHQL_VALIDATION_FAILED", async () => {
  const { result } = await exec("{ books { isbn } }");
  assert.equal(result.errors?.[0].extensions.code, "GRAPHQL_VALIDATION_FAILED");
});

from datetime import datetime, UTC
from zoneinfo import ZoneInfo

from apscheduler.triggers.cron import CronTrigger
from apscheduler.triggers.interval import IntervalTrigger

TZ = ZoneInfo("America/New_York")

def report_trigger() -> CronTrigger:
    return CronTrigger(hour=9, minute=0, timezone=TZ)

def heartbeat_trigger(start: datetime | None = None) -> IntervalTrigger:
    return IntervalTrigger(minutes=15, start_date=start, timezone=UTC)

def next_report(now: datetime | None = None) -> datetime:
    if now is None:
        now = datetime.now(TZ)
    return report_trigger().get_next_fire_time(None, now)

def upcoming(trigger, now: datetime, count: int) -> list[datetime]:
    fire = trigger.get_next_fire_time(None, now)
    out = []
    while fire is not None and len(out) < count:
        out.append(fire)
        fire = trigger.get_next_fire_time(fire, fire)
    return out

