/// <reference types="vitest/config" />
import { getViteConfig } from "astro/config";
export default getViteConfig({ test: {} });

---
interface Props { name: string; price: number; featured?: boolean }
const { name, price, featured = false } = Astro.props;
const label = price === 0 ? "Free" : `$${price}/mo`;
---
<article class:list={["card", { featured }]}>
  <h2>{name}</h2>
  <p class="price">{label}</p>
  {featured && <span class="badge">Most popular</span>}
  <slot />
</article>

import { describe, it, expect } from "vitest";
import { experimental_AstroContainer as AstroContainer } from "astro/container";
import PriceCard from "../src/components/PriceCard.astro";

describe("PriceCard", () => {
  it("renders props and slot", async () => {
    const c = await AstroContainer.create();
    const html = await c.renderToString(PriceCard, { props: { name: "Pro", price: 9 }, slots: { default: "<li>Unlimited recipes</li>" } });
    expect(html).toContain("Pro</h2>");
    expect(html).toContain("$9/mo");
    expect(html).toContain("Unlimited recipes");
    expect(html).not.toContain("Most popular");
  });

  it("featured + free variants", async () => {
    const c = await AstroContainer.create();
    const html = await c.renderToString(PriceCard, { props: { name: "Free", price: 0, featured: true } });
    expect(html).toMatch(/Free<\/p>/);
    expect(html).toMatch(/class="card featured/);
    expect(html).toContain("Most popular");
  });
});

from datetime import datetime

from attrs import define, field, validators


def _non_negative(instance, attribute, value):
    if value < 0:
        raise ValueError(f"{attribute.name} must be >= 0, got {value}")


@define
class Job:
    job_id: int = field(validator=validators.instance_of(int))
    created_at: datetime
    # converter runs first, then validator sees the converted value
    attempts: int = field(default=0, converter=int, validator=_non_negative)
    tags: list[str] = field(factory=list)

{
  "name": "authjs-drizzle-adapter-pglite",
  "private": true,
  "type": "module",
  "scripts": {
    "test": "node --import tsx --test test/*.test.ts"
  },
  "dependencies": {
    "@auth/drizzle-adapter": "1.11.3",
    "@auth/core": "0.41.3",
    "drizzle-orm": "0.45.4",
    "@electric-sql/pglite": "0.5.10"
  },
  "devDependencies": {
    "tsx": "4.23.15",
    "@types/node": "24.19.2"
  }
