function capture() {
  const lines: any[] = [];
  const stream = new Writable({ write(chunk, _e, cb) { lines.push(JSON.parse(chunk.toString())); cb(); } });
  return { lines, stream };
}

test("logs with request id and redacts auth", async () => {
