# In-memory user store for the demo; hashes are computed once at import.
USERS = {
    "alice": {"username": "alice", "hashed_password": pwd.hash("wonderland"), "scopes": ["me", "items:write"]},
    "bob": {"username": "bob", "hashed_password": pwd.hash("builder"), "scopes": ["me"]},
}


class Token(BaseModel):
    access_token: str
    token_type: str = "bearer"


def authenticate(username: str, password: str) -> dict | None:
    user = USERS.get(username)
    if user is None or not pwd.verify(password, user["hashed_password"]):
        return None
    return user


app = FastAPI()


@app.post("/token", response_model=Token)
def login(form: OAuth2PasswordRequestForm = Depends()):
    user = authenticate(form.username, form.password)
    if user is None:
        raise HTTPException(
            status.HTTP_401_UNAUTHORIZED,
            "Incorrect username or password",
            headers={"WWW-Authenticate": "Bearer"},
        )
    # Grant only what was requested AND what the user is allowed to have.
    granted = [s for s in form.scopes if s in user["scopes"]]
    now = datetime.now(timezone.utc)
    payload = {"sub": user["username"], "scopes": granted, "iat": now, "exp": now + TOKEN_TTL}
    return Token(access_token=jwt.encode(payload, SECRET_KEY, algorithm=ALGORITHM))


def current_user(security_scopes: SecurityScopes, token: str = Depends(oauth2)) -> dict:
    challenge = f'Bearer scope="{security_scopes.scope_str}"' if security_scopes.scopes else "Bearer"
    try:
        # Pin the algorithm list; never trust the token's own "alg" header.
        claims = jwt.decode(
            token, SECRET_KEY, algorithms=[ALGORITHM], options={"require": ["exp", "sub"]}
        )
    except jwt.InvalidTokenError:
        raise HTTPException(
            status.HTTP_401_UNAUTHORIZED,
            "Could not validate credentials",
            headers={"WWW-Authenticate": challenge},
        )
    if not set(security_scopes.scopes) <= set(claims.get("scopes", [])):
        raise HTTPException(
            status.HTTP_403_FORBIDDEN,
            "Not enough permissions",
            headers={"WWW-Authenticate": challenge},
        )
    user = USERS.get(claims["sub"])
    if user is None:
        raise HTTPException(
            status.HTTP_401_UNAUTHORIZED,
            "Could not validate credentials",
            headers={"WWW-Authenticate": challenge},
        )
    return user


@app.get("/me")
def me(user: dict = Security(current_user, scopes=["me"])):
    return {"username": user["username"]}


@app.post("/items")
def create_item(name: str, user: dict = Security(current_user, scopes=["items:write"])):
    return {"name": name, "owner": user["username"]}

from datetime import datetime, timedelta, timezone

import jwt
from fastapi.testclient import TestClient

from app import ALGORITHM, SECRET_KEY, app, pwd

client = TestClient(app)


def login(username: str, password: str, scope: str = "me items:write"):
    return client.post("/token", data={"username": username, "password": password, "scope": scope})


def bearer(token: str) -> dict:
    return {"Authorization": f"Bearer {token}"}


def test_login_and_read_profile():
    token = login("alice", "wonderland").json()["access_token"]
    r = client.get("/me", headers=bearer(token))
    assert r.status_code == 200 and r.json() == {"username": "alice"}


def test_scopes_are_intersected_at_login():
    # bob asks for items:write but is only allowed "me", so the token carries just "me"
    token = login("bob", "builder", scope="me items:write").json()["access_token"]
    assert client.get("/me", headers=bearer(token)).status_code == 200
    r = client.post("/items", params={"name": "x"}, headers=bearer(token))
    assert r.status_code == 403
    assert 'scope="items:write"' in r.headers["WWW-Authenticate"]


def test_wrong_password_is_401():
    assert login("alice", "nope").status_code == 401


def test_forged_and_expired_tokens_rejected():
    forged = jwt.encode({"sub": "alice", "scopes": ["me"]}, "not-the-secret", algorithm=ALGORITHM)
    expired = jwt.encode(
        {"sub": "alice", "scopes": ["me"], "exp": datetime.now(timezone.utc) - timedelta(minutes=1)},
        SECRET_KEY,
        algorithm=ALGORITHM,
    )
    for token in (forged, expired):
        assert client.get("/me", headers=bearer(token)).status_code == 401


def test_password_hash_is_argon2_and_verifies():
    h = pwd.hash("s3cret")
    assert h.startswith("$argon2")
    assert pwd.verify("s3cret", h)
    assert not pwd.verify("wrong", h)

