from flask import Flask, jsonify, request
from flask_jwt_extended import (JWTManager, create_access_token, create_refresh_token,
                                get_jwt, get_jwt_identity, jwt_required)

USERS = {"ada": {"password": "lovelace", "role": "admin"}}  # swap for a real store

def create_app(secret="change-me"):
    app = Flask(__name__)
    app.config["JWT_SECRET_KEY"] = secret
    JWTManager(app)

    @app.post("/login")
    def login():
        body = request.get_json(silent=True) or {}
        user = USERS.get(body.get("username"))
        if not user or user["password"] != body.get("password"):
            return jsonify(error="invalid_credentials"), 401
        claims = {"role": user["role"]}
        return jsonify(access=create_access_token(identity=body["username"], additional_claims=claims),
                       refresh=create_refresh_token(identity=body["username"], additional_claims=claims))

    @app.post("/refresh")
    @jwt_required(refresh=True)
    def refresh():
        return jsonify(access=create_access_token(identity=get_jwt_identity(), additional_claims={"role": get_jwt()["role"]}))

    @app.get("/admin")
    @jwt_required()
    def admin():
        if get_jwt().get("role") != "admin":
            return jsonify(error="forbidden"), 403
        return jsonify(user=get_jwt_identity())

    return app

from app import create_app

def client():
    return create_app("a-long-enough-test-secret-key-123").test_client()

def test_login_and_access():
    c = client()
    tokens = c.post("/login", json={"username": "ada", "password": "lovelace"}).get_json()
    r = c.get("/admin", headers={"Authorization": f"Bearer {tokens['access']}"})
    assert r.status_code == 200 and r.get_json() == {"user": "ada"}

def test_refresh_flow():
    c = client()
    tokens = c.post("/login", json={"username": "ada", "password": "lovelace"}).get_json()
    new = c.post("/refresh", headers={"Authorization": f"Bearer {tokens['refresh']}"}).get_json()["access"]
    assert c.get("/admin", headers={"Authorization": f"Bearer {new}"}).status_code == 200
    # an access token cannot be used to refresh
    assert c.post("/refresh", headers={"Authorization": f"Bearer {new}"}).status_code == 422

def test_rejections():
    c = client()
    assert c.post("/login", json={"username": "ada", "password": "x"}).status_code == 401
    assert c.get("/admin").status_code == 401

from flask import Blueprint, Flask, redirect, request, url_for
from flask_login import LoginManager, UserMixin, current_user, login_required, login_user, logout_user
from flask_sqlalchemy import SQLAlchemy
from werkzeug.security import check_password_hash, generate_password_hash

db = SQLAlchemy()
login_manager = LoginManager()
login_manager.login_view = "auth.login"
auth = Blueprint("auth", __name__)


class User(UserMixin, db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    password_hash = db.Column(db.String(255), nullable=False)

    def set_password(self, password: str) -> None:
        self.password_hash = generate_password_hash(password)

    def check_password(self, password: str) -> bool:
        return check_password_hash(self.password_hash, password)


@login_manager.user_loader
def load_user(user_id: str) -> User | None:
    # Flask-Login passes the id as a string. A deleted user returns None (anonymous), not an error.
    return db.session.get(User, int(user_id))


@auth.route("/login", methods=["GET", "POST"])
def login():
    if request.method == "GET":
        return "login form"
    username = request.form.get("username", "")
    user = db.session.scalar(db.select(User).filter_by(username=username))
    if user is None or not user.check_password(request.form.get("password", "")):
        return "bad credentials", 401
    login_user(user)
    nxt = request.args.get("next", "")
    # Only local paths. Reject absolute URLs and "//host" to block open redirects.
    if not nxt.startswith("/") or nxt.startswith("//"):
        nxt = url_for("auth.secret")
    return redirect(nxt)


@auth.get("/secret")
@login_required
def secret():
    return f"secret for {current_user.username}"


@auth.post("/logout")
def logout():
    # POST only, so a GET link or image tag cannot log the user out.
    logout_user()
    return "bye"


def create_app(config: dict | None = None) -> Flask:
    app = Flask(__name__)
    app.config.update(SECRET_KEY="dev-only", SQLALCHEMY_DATABASE_URI="sqlite:///:memory:")
    app.config.update(config or {})
    db.init_app(app)
    login_manager.init_app(app)
    app.register_blueprint(auth)
    return app

from flask import Flask, abort, jsonify
from marshmallow import EXCLUDE, Schema, fields, validate
from webargs.flaskparser import FlaskParser


class JsonParser(FlaskParser):
    # webargs' default 422 response is HTML; return the field errors as JSON
    def handle_error(self, error, req, schema, *, error_status_code, error_headers):
        resp = jsonify(errors=error.messages)
        resp.status_code = error_status_code or 422
        abort(resp)


parser = JsonParser()


class SearchArgs(Schema):
    class Meta:
        unknown = EXCLUDE  # ignore stray query params instead of failing

    q = fields.Str(required=True, validate=validate.Length(min=1))
    page = fields.Int(load_default=1, validate=validate.Range(min=1))
    tags = fields.List(fields.Str(), load_default=list)  # ?tags=a&tags=b
    include_archived = fields.Bool(load_default=False)


class ItemIn(Schema):
    # default unknown=RAISE: extra JSON keys produce a 422
    name = fields.Str(required=True)
    qty = fields.Int(required=True, validate=validate.Range(min=0))


app = Flask(__name__)


@app.get("/search")
@parser.use_kwargs(SearchArgs(), location="query")
def search(q, page, tags, include_archived):
    return jsonify(q=q, page=page, tags=tags, include_archived=include_archived)


@app.post("/items")
@parser.use_args(ItemIn(), location="json")
def create_item(data):
    return jsonify(data), 201

