import { z } from "zod";

const prompt = ChatPromptTemplate.fromMessages([
  ["system", "Classify the support ticket. Reply with JSON: {{\"category\": \"billing\"|\"bug\"|\"other\", \"urgent\": boolean}}"],
  ["human", "{ticket}"],
]);
const Result = z.object({ category: z.enum(["billing", "bug", "other"]), urgent: z.boolean() });

export function buildClassifier(model: BaseChatModel) {
  const chain = prompt.pipe(model).pipe(new StringOutputParser());
  return async (ticket: string) => {
    const raw = await chain.invoke({ ticket });
    const json = raw.replace(/^```(json)?\s*|```\s*$/g, "").trim(); // models often wrap JSON in fences
    return Result.parse(JSON.parse(json));
  };
}

export const formatPrompt = (ticket: string) => prompt.formatMessages({ ticket });

import { test } from "node:test";
import assert from "node:assert/strict";
import { FakeListChatModel } from "@langchain/core/utils/testing";
import { buildClassifier, formatPrompt } from "../src/chain.ts";

test("parses plain JSON output", async () => {
  const classify = buildClassifier(new FakeListChatModel({ responses: ['{"category":"billing","urgent":true}'] }));
  assert.deepEqual(await classify("I was charged twice!"), { category: "billing", urgent: true });
});

test("strips markdown fences", async () => {
  const classify = buildClassifier(new FakeListChatModel({ responses: ['```json\n{"category":"bug","urgent":false}\n```'] }));
  assert.deepEqual(await classify("button broken"), { category: "bug", urgent: false });
});

test("rejects out-of-schema output", async () => {
  const classify = buildClassifier(new FakeListChatModel({ responses: ['{"category":"sales","urgent":"yes"}'] }));
  await assert.rejects(classify("hi"));
});

test("prompt escapes literal braces and fills the variable", async () => {
  const msgs = await formatPrompt("hello");
  assert.match(String(msgs[0].content), /"category"/);
  assert.equal(msgs[1].content, "hello");
});

from langchain_core.language_models.fake_chat_models import GenericFakeChatModel
from langchain_core.messages import AIMessage
from langchain_core.output_parsers import StrOutputParser
from langchain_core.prompts import ChatPromptTemplate
from langchain_core.runnables import Runnable

prompt = ChatPromptTemplate.from_messages([
    ("system", "You are terse."),
    ("human", "{question}"),
])

def fake_model(text: str) -> GenericFakeChatModel:
    # The messages iterator is consumed on every call, so build a fresh model per use.
    return GenericFakeChatModel(messages=iter([AIMessage(content=text)]))

class Flaky:
    """Raises `exc` for the first `fail_times` calls, then delegates to `inner`."""

    def __init__(self, inner: Runnable, fail_times: int, exc: type[Exception] = TimeoutError):
        self.inner, self.fail_times, self.exc = inner, fail_times, exc
        self.calls = 0

    def __call__(self, value):
        self.calls += 1
        if self.calls <= self.fail_times:
            raise self.exc("transient")
        return self.inner.invoke(value)

def build_chain(primary: Runnable, backup: Runnable, attempts: int = 3):
    # Retry happens first, on the primary only. The fallback runs once retries are exhausted.
    retried = primary.with_retry(
        retry_if_exception_type=(TimeoutError,),
        stop_after_attempt=attempts,
        wait_exponential_jitter=False,
    )
    guarded = retried.with_fallbacks([backup], exceptions_to_handle=(TimeoutError,))
    return prompt | guarded | StrOutputParser()

