import { tool } from "@langchain/core/tools";
import { AIMessage, HumanMessage, ToolMessage, type BaseMessage } from "@langchain/core/messages";
import { z } from "zod";

export const convert = tool(async ({ amount, from, to }) => {
  const rates: Record<string, number> = { USD: 1, EUR: 0.9, GBP: 0.8 };
  return String(Math.round((amount / rates[from]) * rates[to] * 100) / 100);
}, {
  name: "convert_currency",
  description: "Convert an amount between USD, EUR and GBP",
  schema: z.object({ amount: z.number().positive(), from: z.enum(["USD", "EUR", "GBP"]), to: z.enum(["USD", "EUR", "GBP"]) }),
});
export const tools = [convert];

export type ChatModel = { invoke: (msgs: BaseMessage[]) => Promise<AIMessage> }; // e.g. new ChatOpenAI().bindTools(tools)

export async function runAgent(model: ChatModel, question: string, maxTurns = 4) {
  const msgs: BaseMessage[] = [new HumanMessage(question)];
  for (let i = 0; i < maxTurns; i++) {
    const ai = await model.invoke(msgs);
    msgs.push(ai);
    if (!ai.tool_calls?.length) return { answer: String(ai.content), msgs };
    for (const call of ai.tool_calls) {
      const t = tools.find((x) => x.name === call.name);
      let content: string;
      try { content = t ? String(await t.invoke(call.args as any)) : `unknown tool ${call.name}`; }
      catch (e) { content = `error: ${(e as Error).message}`; } // schema errors go back to the model
      msgs.push(new ToolMessage({ content, tool_call_id: call.id! }));
    }
  }
  throw new Error("too many turns");
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { AIMessage, ToolMessage } from "@langchain/core/messages";
import { convert, runAgent, type ChatModel } from "../src/agent.ts";

const scripted = (...replies: AIMessage[]): ChatModel => ({ invoke: async () => replies.shift()! });

test("tool validates and runs directly", async () => {
  assert.equal(await convert.invoke({ amount: 100, from: "USD", to: "EUR" }), "90");
  await assert.rejects(convert.invoke({ amount: -1, from: "USD", to: "EUR" } as any));
});

test("loop executes tool calls and returns final answer", async () => {
  const { answer, msgs } = await runAgent(scripted(
    new AIMessage({ content: "", tool_calls: [{ id: "c1", name: "convert_currency", args: { amount: 10, from: "EUR", to: "USD" } }] }),
    new AIMessage("10 EUR is about 11.11 USD."),
  ), "10 EUR in USD?");
  assert.equal(answer, "10 EUR is about 11.11 USD.");
  const tm = msgs.find((m) => m instanceof ToolMessage) as ToolMessage;
  assert.equal(tm.content, "11.11");
  assert.equal(tm.tool_call_id, "c1");
});

test("bad args are returned to the model as an error", async () => {
  const { msgs } = await runAgent(scripted(
    new AIMessage({ content: "", tool_calls: [{ id: "c1", name: "convert_currency", args: { amount: 5, from: "JPY", to: "USD" } }] }),
    new AIMessage("Sorry, unsupported currency."),
  ), "?");
  assert.match(String((msgs[2] as ToolMessage).content), /^error:/);
});

from litestar import Litestar, Request, delete, get
from litestar.connection import ASGIConnection
from litestar.di import Provide
from litestar.exceptions import NotAuthorizedException, PermissionDeniedException
from litestar.handlers import BaseRouteHandler
from litestar.response import Response


class ItemNotFound(Exception):
    pass


class ItemRepo:
    def __init__(self, items: dict[int, str] | None = None):
        self.items = items if items is not None else {1: "widget"}

    def get(self, item_id: int) -> str:
        if item_id not in self.items:
            raise ItemNotFound(item_id)
        return self.items[item_id]

    def delete(self, item_id: int) -> None:
        if self.items.pop(item_id, None) is None:
            raise ItemNotFound(item_id)


async def provide_repo() -> ItemRepo:
    # swap for a real database session in production
    return ItemRepo()


def role_guard(connection: ASGIConnection, handler: BaseRouteHandler) -> None:
    # demo only: trusts a header; use a verified token in production
    required = handler.opt.get("role")
    if required is None:
        return
    role = connection.headers.get("x-role")
    if role is None:
        raise NotAuthorizedException("missing credentials")
    if role != required:
        raise PermissionDeniedException(f"requires role {required}")


@get("/items/{item_id:int}")
async def get_item(item_id: int, repo: ItemRepo) -> dict:
    return {"id": item_id, "name": repo.get(item_id)}


@delete("/items/{item_id:int}", opt={"role": "admin"})
async def delete_item(item_id: int, repo: ItemRepo) -> None:
    repo.delete(item_id)


def item_not_found(request: Request, exc: ItemNotFound) -> Response:
    return Response({"error": "item not found", "id": exc.args[0]}, status_code=404)


ROUTES = [get_item, delete_item]
GUARDS = [role_guard]
HANDLERS = {ItemNotFound: item_not_found}

app = Litestar(
    route_handlers=ROUTES,
    dependencies={"repo": Provide(provide_repo)},
    guards=GUARDS,
    exception_handlers=HANDLERS,
)

import pytest
