import { DateTime, Interval, Duration, Settings } from "luxon";

Settings.throwOnInvalid = true; // fail loudly instead of producing Invalid DateTime

export const toZone = (iso: string, zone: string) => DateTime.fromISO(iso, { setZone: true }).setZone(zone);

export function isBusinessHours(isoUtc: string, zone: string) {
  const t = DateTime.fromISO(isoUtc, { zone: "utc" }).setZone(zone);
  return t.weekday <= 5 && t.hour >= 9 && t.hour < 17;
}

export const meetingsOverlap = (a: [string, string], b: [string, string]) =>
  Interval.fromISO(`${a[0]}/${a[1]}`).overlaps(Interval.fromISO(`${b[0]}/${b[1]}`));

export const humanDuration = (ms: number) => Duration.fromMillis(ms).shiftTo("hours", "minutes").toHuman({ unitDisplay: "short" });

export const addMonthsEndClamped = (iso: string, months: number) => DateTime.fromISO(iso, { zone: "utc" }).plus({ months }).toISODate();

import { test } from "node:test";
import assert from "node:assert/strict";
import { DateTime } from "luxon";
import { addMonthsEndClamped, humanDuration, isBusinessHours, meetingsOverlap, toZone } from "../src/time.ts";

test("zone conversion keeps the instant", () => {
  const t = toZone("2026-07-01T12:00:00Z", "Europe/Paris");
  assert.equal(t.toFormat("HH:mm"), "14:00");
  assert.equal(t.offset, 120);
  assert.equal(t.toUTC().toISO(), "2026-07-01T12:00:00.000Z");
});

test("business hours in the caller's zone", () => {
  assert.equal(isBusinessHours("2026-10-15T17:00:00Z", "America/Anchorage"), true);  // 09:00 AKDT Thu
  assert.equal(isBusinessHours("2026-10-17T20:00:00Z", "America/Anchorage"), false); // Saturday
});

test("interval overlap", () => {
  assert.equal(meetingsOverlap(["2026-01-01T10:00Z", "2026-01-01T11:00Z"], ["2026-01-01T10:30Z", "2026-01-01T12:00Z"]), true);
  assert.equal(meetingsOverlap(["2026-01-01T10:00Z", "2026-01-01T11:00Z"], ["2026-01-01T11:00Z", "2026-01-01T12:00Z"]), false);
});

test("month math clamps to month end; durations read well", () => {
  assert.equal(addMonthsEndClamped("2026-01-31", 1), "2026-02-28");
  assert.match(humanDuration(5_400_000), /1 hr, 30 min/);
});

test("invalid input throws", () => {
  assert.throws(() => DateTime.fromISO("2026-13-45"));
});

from typing import Annotated

import msgspec

PositiveInt = Annotated[int, msgspec.Meta(gt=0)]
Label = Annotated[str, msgspec.Meta(min_length=1, max_length=40)]


class Circle(msgspec.Struct, tag="circle"):
    radius: PositiveInt


class Rect(msgspec.Struct, tag="rect"):
    width: PositiveInt
    height: PositiveInt


# Tagged union: the "type" field selects the variant during decode.
Shape = Circle | Rect


class Order(msgspec.Struct, kw_only=True, forbid_unknown_fields=True):
    id: int
    label: Label
    shapes: list[Shape] = msgspec.field(default_factory=list)


def parse_order(raw: bytes) -> Order:
    return msgspec.json.decode(raw, type=Order)


def order_from_dict(data: dict, strict: bool = True) -> Order:
    return msgspec.convert(data, Order, strict=strict)

