import polars as pl
import pytest
from pandera.errors import SchemaError, SchemaErrors
from schemas import Orders, StrictOrders, validate_orders

def good_frame() -> pl.DataFrame:
    return pl.DataFrame({"order_id": [1, 2], "amount": [9.5, 0.0], "currency": ["USD", "EUR"]})

