class AppSettings(BaseSettings):
    model_config = SettingsConfigDict(
        env_prefix="APP_", env_nested_delimiter="__", extra="ignore",
    )
    debug: bool = False
    api_key: SecretStr = SecretStr("dev-key")
    # default_factory avoids sharing one mutable default instance across objects
    db: DbSettings = Field(default_factory=DbSettings)

    @classmethod
    def settings_customise_sources(
        cls,
        settings_cls,
        init_settings,
        env_settings,
        dotenv_settings,
        file_secret_settings,
    ) -> tuple[PydanticBaseSettingsSource, ...]:
        # first source wins: init > env > yaml > field defaults
        return (init_settings, env_settings, YamlConfigSettingsSource(settings_cls))

def load_settings(yaml_file: Path | None = None, **init: Any) -> AppSettings:
    # a subclass per call lets each test point the YAML source at its own file
    cls = type(
        "LoadedSettings",
        (AppSettings,),
        {"model_config": AppSettings.model_config | {"yaml_file": yaml_file}},
    )
    return cls(**init)

from typing import Annotated, Literal

from fastapi import FastAPI
from pydantic import AfterValidator, BaseModel, Field

app = FastAPI()


def luhn(v: str) -> str:
    total = 0
    for i, ch in enumerate(reversed(v)):
        d = int(ch)
        if i % 2:  # double every second digit from the right
            d = d * 2 - 9 if d > 4 else d * 2
        total += d
    if total % 10:
        raise ValueError("Luhn checksum failed")
    return v


class Card(BaseModel):
    kind: Literal["card"]
    number: Annotated[str, Field(pattern=r"^\d{12,19}$"), AfterValidator(luhn)]


class Bank(BaseModel):
    kind: Literal["bank"]
    iban: Annotated[str, Field(min_length=15, max_length=34)]


# The discriminator must be a Literal on every branch; a plain Union
# would try each branch and produce noisier errors.
Payment = Annotated[Card | Bank, Field(discriminator="kind")]


class Order(BaseModel):
    amount: Annotated[int, Field(gt=0)]
    payment: Payment


@app.post("/orders")
def create_order(order: Order):
