import { fail, redirect, type Actions } from "@sveltejs/kit";
import { z } from "zod";

const Signup = z.object({ email: z.email(), password: z.string().min(8) });
export const users: string[] = [];

export const actions = {
  default: async ({ request, cookies }) => {
    const form = Object.fromEntries(await request.formData()) as Record<string, string>;
    const parsed = Signup.safeParse(form);
    if (!parsed.success) {
      // never echo the password back to the page
      return fail(400, { email: form.email, errors: z.flattenError(parsed.error).fieldErrors });
    }
    if (users.includes(parsed.data.email)) return fail(409, { email: form.email, errors: { email: ["Already registered"] } });
    users.push(parsed.data.email);
    cookies.set("session", `s_${users.length}`, { path: "/", httpOnly: true, sameSite: "lax" });
    redirect(303, "/welcome");
  },
} satisfies Actions;

import { describe, it, expect } from "vitest";
import { isActionFailure, isRedirect } from "@sveltejs/kit";
import { actions } from "../src/routes/signup/+page.server";

function event(fields: Record<string, string>) {
  const jar = new Map<string, string>();
  const ev = { request: new Request("http://app/signup", { method: "POST", body: new URLSearchParams(fields) }), cookies: { set: (k: string, v: string) => jar.set(k, v) } } as any;
  return { ev, jar };
}

describe("signup action", () => {
  it("fails with field errors and no password echo", async () => {
    const r: any = await actions.default(event({ email: "bad", password: "123" }).ev);
    expect(isActionFailure(r)).toBe(true);
    expect(r.status).toBe(400);
    expect(Object.keys(r.data.errors).sort()).toEqual(["email", "password"]);
    expect(r.data.password).toBeUndefined();
  });

  it("sets a cookie and redirects with 303", async () => {
    const { ev, jar } = event({ email: "a@example.com", password: "longenough" });
    const err = await actions.default(ev).catch((e) => e);
    expect(isRedirect(err)).toBe(true);
    expect(err.status).toBe(303);
    expect(err.location).toBe("/welcome");
    expect(jar.get("session")).toBe("s_1");
  });

  it("409 on duplicate email", async () => {
    const r: any = await actions.default(event({ email: "a@example.com", password: "longenough" }).ev);
    expect(r.status).toBe(409);
  });
});

import asyncio
import email.utils
from dataclasses import dataclass
from datetime import datetime, timezone

import httpx
from tenacity import AsyncRetrying, retry_if_exception, stop_after_attempt, wait_exponential

_backoff = wait_exponential(multiplier=0.5, max=8)


@dataclass(frozen=True)
class Repo:
    id: int
    full_name: str
    stargazers_count: int


def _retry_after(response: httpx.Response) -> float | None:
    value = response.headers.get("Retry-After")
    if value is None:
        return None
    if value.isdigit():
        return float(value)
    # Retry-After may also be an HTTP date
    try:
        when = email.utils.parsedate_to_datetime(value)
    except (TypeError, ValueError):
        return None
    return max(0.0, (when - datetime.now(timezone.utc)).total_seconds())


def _wait(retry_state) -> float:
    exc = retry_state.outcome.exception()
    if isinstance(exc, httpx.HTTPStatusError):
        delay = _retry_after(exc.response)
        if delay is not None:
            return delay
    return _backoff(retry_state)


def _should_retry(exc: BaseException) -> bool:
    if isinstance(exc, httpx.TransportError):
        return True
    if isinstance(exc, httpx.HTTPStatusError):
        code = exc.response.status_code
        return code == 429 or code >= 500
    return False


class ApiClient:
    def __init__(self, base_url: str = "https://api.example.com", attempts: int = 3, sleep=asyncio.sleep):
        self.http = httpx.AsyncClient(base_url=base_url, timeout=10)
        self.attempts = attempts
        self.sleep = sleep

    async def _get(self, path: str) -> httpx.Response:
        # A fresh AsyncRetrying per call: retry state lives on the instance,
        # so sharing one across concurrent calls would mix up their attempts.
        retrying = AsyncRetrying(
            stop=stop_after_attempt(self.attempts),
            wait=_wait,
            retry=retry_if_exception(_should_retry),
            sleep=self.sleep,
            reraise=True,  # raise the original error, not tenacity.RetryError
        )
        async for attempt in retrying:
            with attempt:
                r = await self.http.get(path)
                # must raise inside the block, or a 5xx is returned as a success and never retried
                r.raise_for_status()
        return r

    async def get_repo(self, owner: str, name: str) -> Repo:
        r = await self._get(f"/repos/{owner}/{name}")
        d = r.json()
        # pick known fields explicitly so extra API keys are ignored
        return Repo(id=d["id"], full_name=d["full_name"], stargazers_count=d["stargazers_count"])

    async def aclose(self):
        await self.http.aclose()

