const t = initTRPC.context<Context>().create();

const authed = t.procedure.use(({ ctx, next }) => {
  if (!ctx.userId) throw new TRPCError({ code: "UNAUTHORIZED" });
  return next({ ctx: { userId: ctx.userId } });
});

const notes: { id: number; owner: string; text: string }[] = [];

export const appRouter = t.router({
  hello: t.procedure.input(z.object({ name: z.string() })).query(({ input }) => `hello ${input.name}`),
  addNote: authed.input(z.object({ text: z.string().min(1) })).mutation(({ ctx, input }) => {
    const note = { id: notes.length + 1, owner: ctx.userId, text: input.text };
    notes.push(note);
    return note;
  }),
});
export type AppRouter = typeof appRouter;
export const createCaller = t.createCallerFactory(appRouter);

import { test } from "node:test";
import assert from "node:assert/strict";
import { createCaller } from "../src/router.ts";

test("public query", async () => {
  assert.equal(await createCaller({ userId: null }).hello({ name: "dev" }), "hello dev");
});
test("authed mutation", async () => {
  const note = await createCaller({ userId: "u1" }).addNote({ text: "hi" });
  assert.equal(note.owner, "u1");
});
test("unauthorized and invalid input", async () => {
  await assert.rejects(createCaller({ userId: null }).addNote({ text: "x" }), /UNAUTHORIZED/);
  await assert.rejects(createCaller({ userId: "u1" }).addNote({ text: "" }));
});

from typing import Annotated
import typer

app = typer.Typer(no_args_is_help=True)
users = typer.Typer(help="Manage users")
app.add_typer(users, name="users")
DB: dict[str, int] = {}

@users.command("add")
def add_user(name: str, age: Annotated[int, typer.Option(min=0, max=150)] = 0):
    if name in DB:
        typer.echo(f"{name} already exists", err=True)
        raise typer.Exit(code=1)
    DB[name] = age
    typer.echo(f"added {name} ({age})")

@users.command("list")
