{
  "name": "ws-zod-message-protocol",
  "private": true,
  "type": "module",
  "scripts": {
    "test": "node --import tsx --test test/*.test.ts"
  },
  "dependencies": {
    "ws": "8.22.0",
    "zod": "4.6.7"
  },
